package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.MathArithmeticException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.OpenIntToDoubleHashMap.Iterator;
import org.apache.commons.math.util.OpenIntToDoubleHashMap;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for OpenMapRealVector#ebeMultiply
 */
public class OpenMapRealVector_ebeMultiply_TriageGen3Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testEbeMultiply_NormalCase() {
        // Setup a sparse vector: [1.0, 0.0, 2.0, 0.0, 3.0]
        OpenMapRealVector vector = new OpenMapRealVector(5);
        vector.setEntry(0, 1.0);
        vector.setEntry(2, 2.0);
        vector.setEntry(4, 3.0);

        // Multiplier array: [10.0, 5.0, 2.0, 1.0, 0.5]
        double[] v = {10.0, 5.0, 2.0, 1.0, 0.5};

        // Expected: [10.0, 0.0, 4.0, 0.0, 1.5]
        // Note: OpenMapRealVector is sparse, so indices with 0.0 in original vector remain 0.0 (not stored)
        OpenMapRealVector result = vector.ebeMultiply(v);

        assertEquals(5, result.getDimension());
        assertEquals(10.0, result.getEntry(0), EPSILON);
        assertEquals(0.0, result.getEntry(1), EPSILON);
        assertEquals(4.0, result.getEntry(2), EPSILON);
        assertEquals(0.0, result.getEntry(3), EPSILON);
        assertEquals(1.5, result.getEntry(4), EPSILON);
    }

    @Test
    public void testEbeMultiply_EmptyVector() {
        OpenMapRealVector vector = new OpenMapRealVector(3);
        // Vector is all zeros
        double[] v = {1.0, 2.0, 3.0};

        OpenMapRealVector result = vector.ebeMultiply(v);

        assertEquals(3, result.getDimension());
        assertEquals(0.0, result.getEntry(0), EPSILON);
        assertEquals(0.0, result.getEntry(1), EPSILON);
        assertEquals(0.0, result.getEntry(2), EPSILON);
    }

    @Test
    public void testEbeMultiply_MultiplyByZero() {
        OpenMapRealVector vector = new OpenMapRealVector(3);
        vector.setEntry(0, 5.0);
        vector.setEntry(1, 10.0);

        double[] v = {0.0, 1.0, 0.0};

        OpenMapRealVector result = vector.ebeMultiply(v);

        assertEquals(0.0, result.getEntry(0), EPSILON);
        assertEquals(10.0, result.getEntry(1), EPSILON);
    }

    @Test(expected = DimensionMismatchException.class)
    public void testEbeMultiply_DimensionMismatch() {
        OpenMapRealVector vector = new OpenMapRealVector(3);
        double[] v = {1.0, 2.0}; // Length 2 != Dimension 3

        vector.ebeMultiply(v);
    }

    @Test
    public void testEbeMultiply_Immutability() {
        OpenMapRealVector vector = new OpenMapRealVector(2);
        vector.setEntry(0, 1.0);
        double[] v = {5.0, 5.0};

        OpenMapRealVector result = vector.ebeMultiply(v);

        // Verify original vector is unchanged
        assertEquals(1.0, vector.getEntry(0), EPSILON);
        // Verify result is correct
        assertEquals(5.0, result.getEntry(0), EPSILON);
        // Verify result is a different object
        assertNotSame(vector, result);
    }

    @Test
    public void testEbeMultiply_LargeSparseVector() {
        int dim = 1000;
        OpenMapRealVector vector = new OpenMapRealVector(dim);
        int index = 500;
        vector.setEntry(index, 123.456);

        double[] v = new double[dim];
        for (int i = 0; i < dim; i++) {
            v[i] = i;
        }

        OpenMapRealVector result = vector.ebeMultiply(v);

        assertEquals(123.456 * 500, result.getEntry(index), EPSILON);
        assertEquals(0.0, result.getEntry(0), EPSILON);
    }
}
